        __slots__ = fields
        __name__ = name
        __srid_map__ = srid_map

        def __init__(self, *args, **kwargs):
            for field in self.__slots__:
                setattr(self, field, None)
            for field, value in kwargs.items():
                if field in self.__slots__:
                    setattr(self, field, value)
                else:
                    raise ValueError(f"Invalid field {field} for {self.__name__}")
            for field, value in args:
                if field in self.__slots__:
                    setattr(self, field, value)
                else:
                    raise ValueError(f"Invalid field {field} for {self.__name__}")

        def __repr__(self):
            return f"<{self.__name__} {self.x} {self.y}>"

        def __eq__(self, other):
            if not isinstance(other, Point):
                return False
            for field in self.__slots__:
                if getattr(self, field) != getattr(other, field):
                    return False
            return True

        def __ne__(self, other):
            return not self.__eq__(other)

        def __hash__(self):
            return hash((self.__name__, self.x, self.y))

        def __getstate__(self):
            return {field: getattr(self, field) for field in self.__slots__}

        def __setstate__(self, state):
            for field, value in state.items():
                setattr(self, field, value)

        def __reduce__(self):
            return (point_type, (self.__name__, self.__slots__, self.__srid_map__))

    return Point

