def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if lock:
                with lock:
                    key = key(*args, **kwargs)
            if key in cache:
                return cache[key]
            else:
                value = func(*args, **kwargs)
                cache[key] = value
                return value
        return wrapper
    return decorator

