        for i, (existing_key, existing_value) in enumerate(result):
            if key.value == existing_key.value:
                found = True
                if isinstance(value, ruamel.yaml.nodes.MappingNode):
                    result[i] = (key, deep_merge_nodes([(existing_key, existing_value), (key, value)]))
                else:
                    result[i] = (key, value)
