def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """

    # check if spec_content is not None
    if spec_content is None:
        raise IRValidatorException("Spec content is None")

    # check if spec_content is a dictionary
    if not isinstance(spec_content, dict):
        raise IRValidatorException("Spec content is not a dictionary")

    # check if spec_content has all required fields
    required_fields = ["name", "version", "description", "license", "author", "email", "url"]
    for field in required_fields:
        if field not in spec_content:
            raise IRValidatorException(f"Spec content is missing required field: {field}")

    # check if spec_content has all required fields
    optional_fields = ["keywords", "homepage", "bugs", "repository", "dependencies"]
    for field in optional_fields:
        if field not in spec_content:
            spec_content[field] = None

    # check if spec_content["dependencies"] is a list
    if "dependencies" in spec_content and not isinstance(spec_content["dependencies"], list):
        raise IRValidatorException("Spec content dependencies is not a list")

    # check if spec_content["dependencies"] has all required fields
    if "dependencies" in spec_content:
        for dependency in spec_content["dependencies"]:
            required_fields = ["name", "version"]
            for field in required_fields:
                if field not in dependency:
                    raise IRValidatorException(f"Spec content dependencies is missing required field: {field}")

    # return spec_content
    return spec_content

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    # Load YAML file
    with open(yaml_file, 'r') as f:
        data = yaml.load(f, Loader=yaml.FullLoader)

    # Validate that all mandatory fields are present
    for field in cls.MANDATORY_FIELDS:
        if field not in data:
            raise IRValidatorException(f"Mandatory field '{field}' is missing in YAML file '{yaml_file}'")

    # Validate that all fields have the correct type
    for field, field_type in cls.FIELD_TYPES.items():
        if field not in data:
            continue
        if not isinstance(data[field], field_type):
            raise IRValidatorException(f"Field '{field}' in YAML file '{yaml_file}' has incorrect type. Expected {field_type}, got {type(data[field])}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Parameters:
        parser_dict (dict): The parser dictionary
    """
    for key, value in parser_dict.items():
        if key == "include":
            if isinstance(value, list):
                for item in value:
                    if isinstance(item, dict):
                        self._include_groups(item)
            elif isinstance(value, dict):
                self._include_groups(value)

